  const resto = n
    .replace(/\b(que|cual|cuales|de que|en que) (incluye|incluyen|contiene|contienen|trae|traen|viene|vienen|lleva|llevan|hay|consta|consiste)\b/g, ' ')
    .replace(/\b(incluye|incluyen|contiene|contienen|trae|traen)\b/g, ' ')
