  t = t.replace(/\bcuanto (?:cuesta|sale|vale|es)\b/g, ' ').replace(/\bquiero (?:comprar |pagar )?(?:el|la|los|las|un|una)\b/g, ' ').replace(/\bme llevo (?:el|la|los|las)\b/g, ' ').replace(/\b(?:lo|la) compro\b/g, ' ').trim();
