  for (const m of num.matchAll(new RegExp('(\\d+(?:[.,]\\d+)?)\\s?' + MONEDA + '\\b|\\b(?:bs|bob|usd)\\.?\\s?(\\d+(?:[.,]\\d+)?)|\\$\\s?(\\d+(?:[.,]\\d+)?)|(\\d+(?:[.,]\\d+)?)\\s?\\$', 'g'))) if (!esPrecio(m[1] || m[2] || m[3] || m[4])) return 'precio_inventado';
  if (/\$/.test(num)) return 'precio_inventado';
  if (new RegExp('\\b(?:sale|salen|cuesta|cuestan|vale|valen|costaria|costo|precio|tarifa|cobro|cobramos|cobran|pagas|pagar|pagarias|quedan?)\\b\\W{0,14}(?:a |en |de |por |solo |apenas )?(\\d+(?:[.,]\\d+)?)\\b(?!\\s(?:' + U + ')\\b)').test(num)) { const mp = num.match(new RegExp('\\b(?:sale|salen|cuesta|cuestan|vale|valen|costaria|costo|precio|tarifa|cobro|cobramos|cobran|pagas|pagar|pagarias|quedan?)\\b\\W{0,14}(?:a |en |de |por |solo |apenas )?(\\d+(?:[.,]\\d+)?)\\b(?!\\s(?:' + U + ')\\b)')); if (mp && !esPrecio(mp[1])) return 'precio_inventado'; }
  if (new RegExp('\\b(?:cien|ciento|doscientos|trescientos|cuatrocientos|quinientos|mil|diez|quince|veinte|treinta|cuarenta|cincuenta|sesenta|setenta|ochenta|noventa)\\b[^.?!]{0,16}\\b' + MONEDA + '\\b').test(num)) return 'precio_inventado';
  // Los DATOS DECLARADOS del producto (los mismos de `RR_PROMPT`): 208 páginas, 14 eslabones, plan de 21 días, 3 meditaciones de 7, 7 y 5 minutos, 14 capítulos de audio, 50 segundos de muestra, 100% digital. Se aceptan en dígitos Y en palabras;
  // cualquier otra cifra o número («80 %», «20 páginas», «45 minutos», «21 días») rechaza el texto. Los números en palabras de los datos declarados se pasan antes a dígitos.
  const nd = num.replace(/\bdoscient(?:os|as) ocho\b/g, '208').replace(/\bdieciocho\b/g, '18').replace(/\bcatorce\b/g, '14').replace(/\bveintiun(?:o|a)?\b/g, '21');
  const resto = nd
    .replace(/\bcapitulos?\s(?:\d{1,2})(?:(?:\s?,\s?|\s(?:y|e|a|al)\s)\d{1,2})*/g, (x) => ((x.match(/\d+/g) || []).every((k) => Number(k) >= 1 && Number(k) <= 14) ? ' ' : x))
    .replace(/\b208 paginas\b|\b18 paginas\b|\b14 eslabones\b|\b14 capitulos\b|\b3 meditaciones\b|\b21 dias\b|\b5 pasos\b|\b[57](?:(?:\s?,\s?|\s(?:y|e|a|o)\s)[57])* minutos\b|\b50 segundos\b|\b100 ?% (?=digital|virtual|en (?:formato )?(?:digital|pdf)|pdf)/g, ' ');
  for (const m of resto.matchAll(/\d+(?:[.,]\d+)?/g)) if (!esPrecio(m[0])) return 'cifra_no_permitida';
  if (/%/.test(resto) || /\bpor ciento\b/.test(resto)) return 'cifra_no_permitida';
  // Los números en PALABRAS que no son datos declarados: decenas, centenas y miles; «uno»…«nueve» solo junto a un verbo de precio o a una moneda (más abajo).
  if (/\b(?:dieci\w+|veinti\w+|(?:dos|tres|cuatro|quin|seis|sete|ocho|nove)cient[oa]s|mil|millon|millones|cincuenta|sesenta|setenta|ochenta|noventa|once|doce|trece|quince|cuarenta|cien|ciento)\b/.test(resto)) return 'cifra_no_permitida';
  if (new RegExp('\\b(?:sale|salen|cuesta|cuestan|vale|valen|costaria|costo|precio|tarifa|cobro|cobramos|cobran|pagas|pagar|pagarias)\\b[^.?!]{0,16}\\b(?:uno|un|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve)\\b(?!\\s(?:' + U + ')\\b)|\\b(?:uno|un|una|dos|tres|cuatro|cinco|seis|siete|ocho|nueve)\\s' + MONEDA + '\\b').test(num)) return 'precio_inventado';
  return '';
}

// =============================================================================
// UTILIDADES COMUNES DE LOS NODOS DEL FLUJO DE RUBEN (prefijo `cn`)
// =============================================================================
// El constructor las pega entre la librería (`rr.js`, y las `cm*` en los nodos que las piden) y el código de cada nodo. JavaScript plano: sin `require`, `URL`,
// `Buffer` ni `crypto`, y nada de red. Lo que se lee de otro nodo se lee POR NOMBRE y solo si corrió (`isExecuted`): un nodo que no corrió no se lee con `.item`.
// Ningún nodo lee por nombre algo que corre más de una vez en la ejecución (no hay ciclos): `first()` es siempre «el único».

// El nodo `nombre` si existe Y corrió en esta ejecución; si no, null. En un JSON que no lo trae (el de producción no tiene «Entrada de prueba») `$()` lanza.
function cnNodo(nombre) {
  try {
    const n = $(nombre);
    return n && n.isExecuted ? n : null;
  } catch (e) {
    return null;
  }
}
function cnPrimero(nombre) {
  const n = cnNodo(nombre);
  if (!n) return null;
  try {
    const i = n.first();
    return i && i.json ? i.json : null;
  } catch (e) {
    return null;
  }
}
function cnTodos(nombre) {
  const n = cnNodo(nombre);
  if (!n) return [];
  try {
    return n.all().map((i) => (i && i.json) || {});
  } catch (e) {
    return [];
  }
}
function cnCfg() {
  return cnPrimero('Config del negocio') || {};
}
function cnDigitos(v) {
  return String(v === undefined || v === null ? '' : v).replace(/\D/g, '');
}
function cnRecorte(t, max) {
  const s = String(t === undefined || t === null ? '' : t);
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
}
// El texto de una respuesta de Gemini (generateContent, o el nodo de LangChain con `simplify`). '' si vino un error o algo que no se reconoce.
function cnTextoDeGemini(j) {
  if (!j || typeof j !== 'object' || j.error) return '';
  const partes = (c) => (c && Array.isArray(c.parts))
    ? c.parts.map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n') : '';
  if (typeof j.content === 'string') return j.content;
  const c1 = partes(j.content);
  if (c1) return c1;
  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const c2 = cand ? partes(cand.content) : '';
  if (c2) return c2;
  for (const k of ['text', 'transcription', 'output', 'response']) {
    if (typeof j[k] === 'string' && j[k].trim()) return j[k];
  }
  return '';
}
// El objeto JSON que Gemini devolvió como texto; null si no es un objeto.
function cnJsonDeGemini(j) {
  const t = cnTextoDeGemini(j).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  if (!t) return null;
  const m = /\{[\s\S]*\}/.exec(t);
  try {
    const o = JSON.parse(m ? m[0] : t);
    return o && typeof o === 'object' && !Array.isArray(o) ? o : null;
  } catch (e) {
    return null;
  }
}
// La clave de la ficha es el teléfono de origen y solo dígitos: nunca un nombre que toque el prototipo.
function cnClaveValida(from) {
  return /^\d{6,20}$/.test(String(from || ''));
}
// Las fichas de los teléfonos (`staticData.global.ruben`). Un nodo que SOLO LEE no escribe nada en los datos estáticos.
function cnMapaDeFichas(escribir) {
  let sd = null;
  try { sd = $getWorkflowStaticData('global'); } catch (e) { sd = null; }
  if (!sd) return { sd: null, mapa: {} };
  const valido = sd.ruben && typeof sd.ruben === 'object' && !Array.isArray(sd.ruben);
  if (!valido) {
    if (escribir !== true) return { sd: sd, mapa: {} };
